<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';
msp2RequireAccess();
$flash=msp2PullFlash();$error=null;$cuentas=[];$cajas=[];$bancos=[];$movimientos=[];$depositos=[];
$fecha=trim((string)($_GET['fecha']??date('Y-m-d')));$date=DateTimeImmutable::createFromFormat('!Y-m-d',$fecha);if(!$date||$date->format('Y-m-d')!==$fecha)$fecha=date('Y-m-d');
function tdMonto(mixed $v):string{return '$ '.number_format((float)$v,2,',','.');}
try{
    foreach(['msp_tesoreria_cuentas','msp_tesoreria_movimientos','msp_tesoreria_depositos','msp_vw_tesoreria_saldos'] as $t)if(!msp2TableExists($conn,$t))throw new RuntimeException('Falta instalar msp/db/patch_tesoreria_depositos.sql.');
    $cuentas=$conn->query("SELECT * FROM dbo.msp_vw_tesoreria_saldos WHERE activo=1 ORDER BY CASE tipo_cuenta WHEN N'CAJA' THEN 0 ELSE 1 END,nombre_cuenta")->fetchAll()?:[];
    foreach($cuentas as $c){if(($c['tipo_cuenta']??'')==='CAJA')$cajas[]=$c;else $bancos[]=$c;}
    $stmt=$conn->prepare("SELECT m.*,c.nombre_cuenta,c.tipo_cuenta,c.banco FROM dbo.msp_tesoreria_movimientos m JOIN dbo.msp_tesoreria_cuentas c ON c.id_cuenta_tesoreria=m.id_cuenta_tesoreria WHERE m.fecha_movimiento=:fecha ORDER BY m.fecha_registro DESC,m.id_movimiento_tesoreria DESC");$stmt->execute([':fecha'=>$fecha]);$movimientos=$stmt->fetchAll()?:[];
    $stmt=$conn->prepare("SELECT d.*,cc.nombre_cuenta caja,cb.nombre_cuenta cuenta_banco,cb.banco FROM dbo.msp_tesoreria_depositos d JOIN dbo.msp_tesoreria_cuentas cc ON cc.id_cuenta_tesoreria=d.id_cuenta_caja JOIN dbo.msp_tesoreria_cuentas cb ON cb.id_cuenta_tesoreria=d.id_cuenta_banco WHERE d.fecha_deposito=:fecha ORDER BY d.id_deposito_tesoreria DESC");$stmt->execute([':fecha'=>$fecha]);$depositos=$stmt->fetchAll()?:[];
}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No fue posible cargar tesorería.';}
$entradaDia=0.0;$salidaDia=0.0;foreach($movimientos as $m){if(($m['estado_movimiento']??'')!=='VIGENTE')continue;if(($m['naturaleza']??'')==='E')$entradaDia+=(float)$m['monto'];else $salidaDia+=(float)$m['monto'];}
?>
